 private void navigate(String dest){switch(dest){case "home":home();break;case "explore":explore();break;case "search":search();break;case "stations":stations();break;default:account();}}
 private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);b.setPadding(dp(10),dp(4),dp(10),dp(4));b.setMinHeight(dp(40));b.setMinimumHeight(dp(40));b.setMinWidth(0);b.setMinimumWidth(0);b.setOnClickListener(v->action.run());return b;}
 private void pill(View v,int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(12));v.setBackground(d);}
 private void note(LinearLayout host,String s){TextView t=text(s,13,muted);t.setPadding(dp(16),dp(10),dp(16),dp(10));host.addView(t);}
 private void screen(String name,String title){generation++;listGeneration++;listLoading=false;releaseWatch();closeWeb();if(!name.equals("login")&&!name.equals("auth"))returnAfterLogin=null;screen=name;body.removeAllViews();heading.setText(name.equals("home")||name.equals("history")?"SOOP":title);updateNavigation(name);header.setVisibility(View.VISIBLE);nav.setVisibility(View.VISIBLE);if(full){full=false;applyImmersive();setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);}}
 private LinearLayout listShell(String title,String name){screen(name,title);LinearLayout box=column();body.addView(box,new FrameLayout.LayoutParams(-1,-1));listStatus=text("불러오는 중…",13,muted);listStatus.setPadding(dp(16),dp(8),dp(16),dp(8));box.addView(listStatus);rows.clear();cards=new Cards();RecyclerView list=new RecyclerView(this);list.setLayoutManager(new LinearLayoutManager(this));list.setAdapter(cards);list.setClipToPadding(false);list.setPadding(0,0,0,dp(12));list.addOnScrollListener(new RecyclerView.OnScrollListener(){@Override public void onScrolled(RecyclerView view,int dx,int dy){if(dy>0&&more!=null&&more.isEnabled()&&more.getVisibility()==View.VISIBLE&&!view.canScrollVertically(1))loadList(true);}});pullRefresh=new androidx.swiperefreshlayout.widget.SwipeRefreshLayout(this);pullRefresh.setColorSchemeColors(blue);pullRefresh.addView(list);pullRefresh.setOnRefreshListener(()->{if(screen.equals("history")){pullRefresh.setRefreshing(false);history();}else{page=1;loadList(false);}});box.addView(pullRefresh,new LinearLayout.LayoutParams(-1,0,1));more=button("더 보기",()->loadList(true));box.addView(more);return box;}
 private void updateNavigation(String name){if(nav==null)return;for(int i=0;i<nav.getChildCount();i++){LinearLayout tab=(LinearLayout)nav.getChildAt(i);boolean active=("nav."+name).equals(tab.getTag())||(name.equals("history")&&i==0)||(name.equals("station")&&i==2);tab.setSelected(active);((ImageView)tab.getChildAt(0)).setColorFilter(active?blue:muted);((TextView)tab.getChildAt(1)).setTextColor(active?blue:muted);}}
 private void home(){if(historyHome)history();else homeLive();}
 private void homeTab(String value){homeSection=value;categoryId="";categoryTitle="";historyHome=false;homeLive();}
 private void mainTabs(LinearLayout box,boolean records){
  LinearLayout tabs=row();tabs.setPadding(dp(12),dp(6),dp(12),dp(10));String[] labels={"탐색","추천","라이브","기록"};String[] values={"explore","recommended","live","history"};
  for(int n=0;n<labels.length;n++){String value=values[n];Button tab=button(labels[n],()->{if(value.equals("explore"))explore();else if(value.equals("history"))history();else homeTab(value);});boolean selected=records?value.equals("history"):value.equals(homeSection);tab.setSelected(selected);tab.setTextColor(selected?blue:Color.WHITE);pill(tab,selected?0xff193849:panel);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(36),1);lp.setMargins(dp(3),0,dp(3),0);tabs.addView(tab,lp);}box.addView(tabs,0);
 }
 private void homeLive(){
  historyHome=false;feedCards=homeSection.equals("recommended")&&categoryId.isEmpty();LinearLayout box=listShell("SOOP","home");mainTabs(box,false);streamerStrip=row();streamerStrip.setPadding(dp(12),dp(6),dp(12),dp(12));HorizontalScrollView stories=new HorizontalScrollView(this);stories.setHorizontalScrollBarEnabled(false);stories.addView(streamerStrip);box.addView(stories,1);
  LinearLayout caption=row();caption.setPadding(dp(16),dp(4),dp(10),dp(2));TextView title=text(categoryTitle.isEmpty()?(feedCards?"지금, 라이브":"LIVE 전체"):categoryTitle,19,Color.WHITE);title.setTypeface(null,Typeface.BOLD);caption.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button sort=button(BrowseOptions.LIVE_LABELS[BrowseOptions.index(BrowseOptions.LIVE_KEYS,liveOrder)]+" ▾",this::liveSort);sort.setTag("live.sort");caption.addView(sort);if(!categoryId.isEmpty())caption.addView(button("전체",()->{categoryId="";categoryTitle="";homeLive();}));box.addView(caption,2);page=1;loadList(false);
 }
 private void liveSort(){new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("라이브 정렬").setSingleChoiceItems(BrowseOptions.LIVE_LABELS,BrowseOptions.index(BrowseOptions.LIVE_KEYS,liveOrder),(dialog,index)->{dialog.dismiss();setLiveOrder(BrowseOptions.LIVE_KEYS[index]);}).setNegativeButton("취소",null).show();}
 private void setLiveOrder(String order){BrowseOptions.checked(BrowseOptions.LIVE_KEYS,order);liveOrder=order;prefs.edit().putString("liveOrder",order).apply();homeSection="live";if(miniPlayer){feedCards=false;View sort=root.findViewWithTag("live.sort");if(sort instanceof Button)((Button)sort).setText(BrowseOptions.LIVE_LABELS[BrowseOptions.index(BrowseOptions.LIVE_KEYS,liveOrder)]+" ▾");loadList(false);}else homeLive();}
 private void videoSort(){new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("동영상 정렬").setSingleChoiceItems(BrowseOptions.VIDEO_LABELS,BrowseOptions.index(BrowseOptions.VIDEO_KEYS,videoOrder),(dialog,index)->{dialog.dismiss();videoOrder=BrowseOptions.VIDEO_KEYS[index];prefs.edit().putString("videoOrder",videoOrder).apply();station(stationId,stationType);}).setNegativeButton("취소",null).show();}
 private void searchSort(){new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("검색 정렬").setSingleChoiceItems(BrowseOptions.SEARCH_LABELS,BrowseOptions.index(BrowseOptions.SEARCH_KEYS,searchOrder),(dialog,index)->{dialog.dismiss();searchOrder=BrowseOptions.SEARCH_KEYS[index];prefs.edit().putString("searchOrder",searchOrder).apply();search();}).setNegativeButton("취소",null).show();}
 private String profile(String id){return ServiceUrls.userId(id)?"https://profile.img.sooplive.com/LOGO/"+id.substring(0,Math.min(2,id.length()))+"/"+id+"/"+id+".jpg":"";}
 private void populateStreamers(){if(streamerStrip==null)return;streamerStrip.removeAllViews();LinkedHashMap<String,ContentItem> people=new LinkedHashMap<>();Set<String> saved=prefs.getStringSet("favorites",Collections.emptySet());for(String id:saved)people.put(id,new ContentItem(id,id,"",nicknames.getOrDefault(id,id),"","",false));for(ContentItem item:rows)if(!people.containsKey(item.user)&&people.size()<14)people.put(item.user,item);
  for(ContentItem item:people.values()){LinearLayout person=column();person.setGravity(Gravity.CENTER);person.setPadding(dp(5),dp(3),dp(5),0);ImageView avatar=new ImageView(this);Glide.with(this).load(profile(item.user)).circleCrop().into(avatar);GradientDrawable border=new GradientDrawable();border.setColor(panel);border.setShape(GradientDrawable.OVAL);border.setStroke(dp(2),blue);avatar.setBackground(border);avatar.setPadding(dp(3),dp(3),dp(3),dp(3));person.addView(avatar,new LinearLayout.LayoutParams(dp(56),dp(56)));TextView name=text(html(item.nick.isEmpty()?item.user:item.nick),11,Color.WHITE);name.setSingleLine();name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setGravity(Gravity.CENTER);person.addView(name,new LinearLayout.LayoutParams(dp(62),dp(26)));person.setContentDescription("방송국 "+item.user);person.setOnClickListener(v->station(item.user,"home"));streamerStrip.addView(person);}
 }
 private void explore(){
  screen("explore","탐색");ScrollView scroll=new ScrollView(this);LinearLayout box=column();box.setPadding(dp(16),dp(8),dp(16),dp(20));scroll.addView(box);body.addView(scroll,new FrameLayout.LayoutParams(-1,-1));Button search=button("⌕   방송 · 스트리머 검색",this::search);search.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);pill(search,panel);box.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));TextView title=text("카테고리",22,Color.WHITE);title.setTypeface(null,Typeface.BOLD);title.setPadding(0,dp(24),0,dp(16));box.addView(title);int request=generation;io.execute(()->{try{JSONArray categories=api.categories();main.post(()->{if(request!=generation)return;for(int i=0;i<categories.length();i++){JSONObject group=categories.optJSONObject(i);if(group==null)continue;TextView label=text(group.optString("category_name"),17,Color.WHITE);label.setPadding(0,dp(16),0,dp(10));box.addView(label);JSONArray items=group.optJSONArray("child");if(items==null)continue;for(int j=0;j<items.length();j+=2){LinearLayout row=row();for(int k=j;k<Math.min(j+2,items.length());k++){JSONObject c=items.optJSONObject(k);if(c==null)continue;String id=c.optString("category_no"),name=c.optString("category_name");Button chip=button(name,()->{categoryId=id;categoryTitle=name;homeSection="live";homeLive();});chip.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);pill(chip,panel);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(64),1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(chip,lp);}box.addView(row);}}});}catch(Exception e){main.post(()->{if(request==generation)note(box,"카테고리를 불러오지 못했습니다");});}});
 }
 private void history(){historyHome=true;LinearLayout box=listShell("홈","history");mainTabs(box,true);for(WatchHistory.Entry entry:history.recent())rows.add(entry.item);cards.notifyDataSetChanged();listStatus.setText(rows.isEmpty()?"아직 보던 VOD가 없습니다 · 다시보기를 재생하면 여기에 저장됩니다":"최근 시청 "+rows.size()+"개 · 누르면 이어보기 · 길게 누르면 관리");more.setVisibility(View.GONE);if(!rows.isEmpty())box.addView(button("기록 전체 삭제",()->new androidx.appcompat.app.AlertDialog.Builder(this).setMessage("이 기기에 저장된 VOD 시청 기록을 모두 삭제할까요?").setPositiveButton("삭제",(d,w)->{history.clear();history();}).setNegativeButton("취소",null).show()),2);}
 private void historyActions(ContentItem item){WatchHistory.Entry entry=history.find(item.id);if(entry==null)return;new androidx.appcompat.app.AlertDialog.Builder(this).setTitle(html(item.title)).setItems(new String[]{"이어보기","처음부터 보기","이 기록 삭제"},(d,n)->{if(n==0)watch(item);else if(n==1)watch(item,false);else{history.remove(item.id);history();}}).show();}
 private void search(){
  LinearLayout box=listShell("검색","search");LinearLayout tools=column();LinearLayout searchBar=row();searchBar.setPadding(dp(10),0,dp(6),0);pill(searchBar,panel);EditText input=new EditText(this);input.setTag("search.query");input.setSingleLine();input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);input.setText(keyword);input.setTextColor(Color.WHITE);input.setHintTextColor(muted);input.setHint("방송, 스트리머, VOD 검색");input.setBackgroundColor(Color.TRANSPARENT);searchBar.addView(input,new LinearLayout.LayoutParams(0,dp(48),1));searchBar.addView(button("검색",()->{keyword=input.getText().toString().trim();hideKeyboard(input);page=1;loadList(false);}),new LinearLayout.LayoutParams(-2,dp(44)));tools.setPadding(dp(14),dp(4),dp(14),dp(4));tools.addView(searchBar);
  LinearLayout types=row();String[] labels={"통합","스트리머","LIVE","VOD"},modes={"all","streamer","live","vod"};for(int i=0;i<labels.length;i++){String mode=modes[i];Button tab=button(labels[i],()->{keyword=input.getText().toString().trim();hideKeyboard(input);searchMode=mode;searchVod=mode.equals("vod");page=1;search();});tab.setSelected(mode.equals(searchMode));tab.setTextColor(mode.equals(searchMode)?blue:muted);types.addView(tab,new LinearLayout.LayoutParams(0,-2,1));}tools.addView(types);if(!searchMode.equals("streamer")&&!searchMode.equals("all")){Button sort=button(BrowseOptions.SEARCH_LABELS[BrowseOptions.index(BrowseOptions.SEARCH_KEYS,searchOrder)]+" ▾",()->{keyword=input.getText().toString().trim();searchSort();});sort.setTag("search.sort");tools.addView(sort);}box.addView(tools,0);input.setOnEditorActionListener((v,a,e)->{keyword=input.getText().toString().trim();hideKeyboard(input);page=1;loadList(false);return true;});
  if(keyword.isEmpty()){listStatus.setText("SOOP 방송·스트리머·다시보기를 검색하세요");more.setVisibility(View.GONE);}else loadList(false);
 }
 private void hideKeyboard(View view){android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(keyboard!=null)keyboard.hideSoftInputFromWindow(view.getWindowToken(),0);view.clearFocus();}
 private void station(String user,String type){
  if(!ServiceUrls.userId(user)){toast("방송국 ID를 확인하세요");return;}stationId=user;stationType=type;LinearLayout box=listShell("방송국","station");
  stationHeader=column();stationHeader.setPadding(dp(16),dp(16),dp(16),dp(8));LinearLayout profileRow=row();ImageView avatar=new ImageView(this);Glide.with(this).load(profile(user)).circleCrop().into(avatar);profileRow.addView(avatar,new LinearLayout.LayoutParams(dp(64),dp(64)));LinearLayout identity=column();identity.setPadding(dp(14),0,0,0);TextView name=text(nicknames.getOrDefault(user,user),23,Color.WHITE);name.setTypeface(null,Typeface.BOLD);identity.addView(name);TextView id=text("@"+user,12,muted);identity.addView(id);profileRow.addView(identity,new LinearLayout.LayoutParams(0,-2,1));Button favorite=button(prefs.getStringSet("favorites",Collections.emptySet()).contains(user)?"★ 즐겨찾기":"☆ 즐겨찾기",()->{favorite(user);station(user,type);});pill(favorite,panel);profileRow.addView(favorite);stationHeader.addView(profileRow);Button live=button("●  LIVE 방송 보기",()->watch(new ContentItem(user,user,user+" LIVE",nicknames.getOrDefault(user,user),"","",false)));live.setTextColor(blue);live.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);stationHeader.addView(live,new LinearLayout.LayoutParams(-1,dp(44)));box.addView(stationHeader,0);
  LinearLayout tabs=row();String[] labels={"홈","동영상","다시보기","클립","게시글"},values={"home","all","review","clip","posts"};for(int n=0;n<labels.length;n++){String value=values[n];Button tab=button(labels[n],()->station(user,value));tab.setSelected(type.equals(value));tab.setTextColor(type.equals(value)?blue:Color.WHITE);tabs.addView(tab,new LinearLayout.LayoutParams(0,dp(44),1));}box.addView(tabs,1);
  if(type.equals("home")||type.equals("posts")){pullRefresh.setVisibility(View.GONE);more.setVisibility(View.GONE);listStatus.setVisibility(View.GONE);ScrollView scroll=new ScrollView(this);LinearLayout content=column();scroll.addView(content);box.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));int request=generation;
   if(type.equals("home")){TextView label=text("최근 동영상",18,Color.WHITE);label.setPadding(dp(16),dp(18),0,dp(8));content.addView(label);LinearLayout latestItems=column();content.addView(latestItems);io.execute(()->{try{List<ContentItem> latest=api.station(user,"all",1);main.post(()->{if(request!=generation)return;for(int i=0;i<Math.min(4,latest.size());i++){ContentItem item=latest.get(i);nicknames.put(user,item.nick);name.setText(html(item.nick));latestItems.addView(channelVideo(item));}});}catch(Exception e){main.post(()->{if(request==generation)note(content,"동영상을 불러오지 못했습니다");});}});}
   TextView posts=text("게시글",18,Color.WHITE);posts.setPadding(dp(16),dp(18),0,dp(8));content.addView(posts);loadChannelPosts(content,user,request);
  }else{Button sort=button(BrowseOptions.VIDEO_LABELS[BrowseOptions.index(BrowseOptions.VIDEO_KEYS,videoOrder)]+" ▾",this::videoSort);sort.setTag("video.sort");box.addView(sort,2);page=1;loadList(false);}
 }
