 private void loadList(boolean next){
  if(next&&listLoading)return;if(screen.equals("history"))return;
  if(screen.equals("search")&&keyword.isEmpty()){if(pullRefresh!=null)pullRefresh.setRefreshing(false);listStatus.setText("검색어를 입력하세요");return;}
  int requestedPage=next?page+1:1,request=++listGeneration;String kind=screen,user=stationId,type=stationType,q=keyword,mode=searchMode,category=categoryId,liveSort=liveOrder,vodSort=videoOrder,resultSort=searchOrder;boolean vod=searchVod;listLoading=true;
  more.setText("더 보기");more.setOnClickListener(v->loadList(true));more.setEnabled(false);more.setVisibility(View.VISIBLE);listStatus.setText("불러오는 중…");
  io.execute(()->{try{SearchPage searchResult=kind.equals("search")?api.searchPage(q,mode,requestedPage,resultSort):null;List<ContentItem> found=searchResult!=null?searchResult.items:kind.equals("station")?api.station(user,type,requestedPage,vodSort):api.liveList(category,liveSort,requestedPage);
   main.post(()->{if(request!=listGeneration)return;listLoading=false;page=requestedPage;if(pullRefresh!=null)pullRefresh.setRefreshing(false);if(!next)rows.clear();List<ContentItem> unique=BrowseOptions.additions(rows,found);rows.addAll(unique);cards.notifyDataSetChanged();for(ContentItem item:found)if(!item.nick.isEmpty())nicknames.put(item.user,item.nick);if(kind.equals("home")&&requestedPage==1)populateStreamers();listStatus.setVisibility(kind.equals("home")&&!found.isEmpty()?View.GONE:View.VISIBLE);String order=kind.equals("home")?BrowseOptions.LIVE_LABELS[BrowseOptions.index(BrowseOptions.LIVE_KEYS,liveSort)]+" · ":kind.equals("station")?BrowseOptions.VIDEO_LABELS[BrowseOptions.index(BrowseOptions.VIDEO_KEYS,vodSort)]+" · ":"";listStatus.setText(kind.equals("search")?(rows.isEmpty()?"검색 결과가 없습니다":mode.equals("all")?"통합 검색 · 각 탭에서 전체 결과 보기":rows.size()+"개 불러옴"+(searchResult.hasMore?"":" · 마지막 결과")):order+rows.size()+"개"+(found.isEmpty()?" · 마지막 목록입니다":""));more.setEnabled(true);more.setVisibility(found.isEmpty()||(searchResult!=null&&!searchResult.hasMore)?View.GONE:View.VISIBLE);});
  }catch(Exception e){main.post(()->{if(request!=listGeneration)return;listLoading=false;if(pullRefresh!=null)pullRefresh.setRefreshing(false);listStatus.setVisibility(View.VISIBLE);listStatus.setText("목록을 가져오지 못했습니다 · "+safeError(e));more.setText("다시 시도");more.setEnabled(true);more.setOnClickListener(v->loadList(next));});}});
 }
