  LinearLayout options=column();TreeMap<Integer,Runnable> choices=new TreeMap<>(Collections.reverseOrder());TreeMap<Integer,String> labels=new TreeMap<>(Collections.reverseOrder());
  for(Tracks.Group g:player.getCurrentTracks().getGroups())if(g.getType()==C.TRACK_TYPE_VIDEO)for(int i=0;i<g.length;i++){Format f=g.getTrackFormat(i);if(g.isTrackSupported(i)&&f.height>0&&f.height<=1080){TrackSelectionOverride override=new TrackSelectionOverride(g.getMediaTrackGroup(),i);choices.put(f.height,()->{if(player!=null){qualityRequest++;manualLiveQuality=true;if(current!=null&&!current.vod&&info!=null)for(LiveQuality q:info.qualities)if(q.height==f.height){info.selectedQuality=q.id;break;}player.setTrackSelectionParameters(player.getTrackSelectionParameters().buildUpon().clearOverridesOfType(C.TRACK_TYPE_VIDEO).setOverrideForType(override).build());}});labels.put(f.height,f.height+"p");}}
