  if(current!=null&&!current.vod&&info!=null)for(LiveQuality q:info.qualities)if(q.height==0||q.height>1080)options.addView(button(q.height>1080?"원본 · "+q.height+"p":q.label,()->{dialog[0].dismiss();switchLiveQuality(q.id);}));
